# region: render
def render(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: sift
def sift(xs):
    return [v for v in xs if v % 2 == 0]

# region: intake
def intake(xs):
    return {'n': len(xs) - 1, 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: digest
def digest(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return digest(intake(sift(render(raw))))

